node -e '
const fs = require("fs");
const testBC = `Status: success
Mode: TRACE

## BrainCode

\`\`\`braincode
MODE TRACE
ENTRYPOINT Conversation
CONVO Conversation {
  TURN t1 SPEAKER=USER {
    FOOBAR BAZ
  }
}
\`\`\`

## Needs coverage

| need | kind | expressed by | status |
|---|---|---|---|
| n1 | claim | foo | covered |

## Translation report

- Check: rag check
`;
fs.writeFileSync("/output/translation.md", testBC);
' && node /kit/rag.mjs check --translation /output/translation.md
